public class IntStatsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("mixed values", "[1, 5, 14]",
                java.util.Arrays.toString(IntStats.minMaxSum(new int[] { 3, 1, 4, 1, 5 })));
        check("single element", "[7, 7, 7]",
                java.util.Arrays.toString(IntStats.minMaxSum(new int[] { 7 })));
        check("negative values", "[-8, 4, -6]",
                java.util.Arrays.toString(IntStats.minMaxSum(new int[] { -2, -8, 4 })));
        check("all identical", "[2, 2, 8]",
                java.util.Arrays.toString(IntStats.minMaxSum(new int[] { 2, 2, 2, 2 })));
        check("already sorted", "[1, 4, 10]",
                java.util.Arrays.toString(IntStats.minMaxSum(new int[] { 1, 2, 3, 4 })));
        check("empty array", "[0, 0, 0]",
                java.util.Arrays.toString(IntStats.minMaxSum(new int[0])));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
