public class IntStats {

    public static int[] minMaxSum(int[] values) {
        if (values.length == 0) {
            return new int[] { 0, 0, 0 };
        }
        java.util.IntSummaryStatistics stats =
                java.util.stream.IntStream.of(values).summaryStatistics();
        return new int[] { stats.getMin(), stats.getMax(), (int) stats.getSum() };
    }
}
